import (
	context "context"
	fern "github.com/x-fern-global-parameters/fern"
	fernclient "github.com/x-fern-global-parameters/fern/client"
)

client := fernclient.NewClient()
response, err := client.Products.Search(
	context.TODO(),
	&fern.SearchProductsRequest{
		RegionID: "regionId",
	},
)

